// Turns rules/*.yaml into src/data.generated.ts so Workers and browsers can import them.
// --check: fail if the generated file is out of date (used in CI).
import { readFileSync, readdirSync, writeFileSync, existsSync } from "node:fs";
import { parse } from "yaml";

const root = new URL("../../../rules/", import.meta.url);
const out = new URL("../src/data.generated.ts", import.meta.url);

const read = (f) => parse(readFileSync(new URL(f, root), "utf8"));
const countries = readdirSync(new URL("countries/", root))
  .filter((f) => f.endsWith(".yaml") && !f.startsWith("_"))
  .sort()
  .map((f) => read(`countries/${f}`));

const data = { euBase: read("eu-base.yaml"), countries, officialHosts: read("official-hosts.yaml") };
const text = `// Generated by packages/rules/scripts/build-rules.mjs from rules/*.yaml. Do not edit by hand.\n// Rules data: CC BY 4.0, "PawID rules".\nexport const RAW = ${JSON.stringify(data, null, 2)} as const;\n`;

if (process.argv.includes("--check")) {
  if (!existsSync(out) || readFileSync(out, "utf8") !== text) {
    console.error("rules data is out of date: run npm run build:rules -w @pawid/rules and commit the result");
    process.exit(1);
  }
  console.log("rules data up to date");
} else {
  writeFileSync(out, text);
  console.log(`data.generated.ts: EU base + ${countries.length} countries`);
}
